window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-659f3789f0bde91b"]={"versions": [{"id": "FIG-659f3789f0bde91b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des polling-basierten Sende-Bestätigungsablaufs (Transmit confirmation polling driven) innerhalb des AUTOSAR-Kommunikationsstapels der Classic Platform (Communication Stack / CAN-Treiber und CAN-Interface). Es zeigt die Interaktion zwischen Betriebssystem-/Scheduler-Ebene, BSW-Modulen und Hardware-Peripherie während der zyklischen Abarbeitung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Entitäten:</p>\n<ul class=\"fig-list\">\n<li><code>BSW Scheduler</code> (Scheduler-Akteur/Task-Kontext)</li>\n<li><code>CanIf User</code> (obere Schicht / PDU Router, CanNm etc.)</li>\n<li><code>«module» CanIf</code> (CAN Interface)</li>\n<li><code>«module» Can</code> (CAN Driver, dargestellt mit Multi-Core-/Parallelitäts-Symbol)</li>\n<li><code>«Peripheral» CanController</code> (CAN-Controller-Hardware)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Funktionsaufrufe:</p>\n<ul class=\"fig-list\">\n<li><code>Can_MainFunction_Write()</code>: Zyklischer Aufruf des Treibers durch den Scheduler</li>\n<li><code>Check for pending TX confirmations()</code>: Hardware-Abfrage des CAN-Treibers an den Controller</li>\n<li><code>CanIf_TxConfirmation(PduIdType)</code>: Callback des CAN-Treibers an das CAN-Interface</li>\n<li><code>&lt;User_TxConfirmation&gt;(PduIdType)</code>: Konfigurierbarer Callback des CAN-Interfaces an die übergeordnete Schicht (CanIf-Nutzer)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf ist in einen <code>loop Cyclic Task of Interface</code> eingebettet:</p>\n<ol class=\"fig-list\">\n<li><code>BSW Scheduler</code> ruft synchron <code>Can_MainFunction_Write()</code> auf dem Modul <code>Can</code> auf.</li>\n<li><code>Can</code> prüft hardwarenah beim <code>CanController</code> ausstehende Sende-Bestätigungen (<code>Check for pending TX confirmations()</code>).</li>\n<li>In einem <code>alt</code>-Fragment (<code>Pending Tx confirmation</code>) wird differenziert:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[Tx confirmation is pending ]</code>: <code>Can</code> ruft <code>CanIf_TxConfirmation(PduIdType)</code> auf; <code>CanIf</code> leitet die Bestätigung über <code>&lt;User_TxConfirmation&gt;(PduIdType)</code> an den entsprechenden <code>CanIf User</code> weiter. Nach Rückkehr beider Aufrufe kehrt die Kontrolle zu <code>Can</code> zurück.</li>\n<li>Zweig <code>[No Tx confirmation is pending]</code>: Keine weiteren Aktionen im Treiber oder Interface.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>Can_MainFunction_Write()</code> kehrt zum <code>BSW Scheduler</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert das Polling-Verhalten im Gegensatz zum interruptgetriebenen Bestätigungspfad. Bei Verzicht auf TX-Interrupts des Controllers muss die zyklische Task <code>Can_MainFunction_Write()</code> in ausreichender Frequenz durch den BSW Scheduler getaktet werden, um Latenzen bei der Sende-Bestätigung an obere Schichten (<code>CanIf User</code>) zu minimieren. Die PduIdType-Zuordnung erfolgt hierarchisch über die konfigurierte Transmit-PDU-ID.</p>"}, {"id": "FIG-c46f90c9325a2a03", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des polling-basierten Sende-Bestätigungsablaufs (Transmit confirmation polling driven) innerhalb des AUTOSAR-Kommunikationsstapels der Classic Platform (Communication Stack / CAN-Treiber und CAN-Interface). Es zeigt die Interaktion zwischen Betriebssystem-/Scheduler-Ebene, BSW-Modulen und Hardware-Peripherie während der zyklischen Abarbeitung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Entitäten:</p>\n<ul class=\"fig-list\">\n<li><code>BSW Scheduler</code> (Scheduler-Akteur/Task-Kontext)</li>\n<li><code>CanIf User</code> (obere Schicht / PDU Router, CanNm etc.)</li>\n<li><code>«module» CanIf</code> (CAN Interface)</li>\n<li><code>«module» Can</code> (CAN Driver, dargestellt mit Multi-Core-/Parallelitäts-Symbol)</li>\n<li><code>«Peripheral» CanController</code> (CAN-Controller-Hardware)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Funktionsaufrufe:</p>\n<ul class=\"fig-list\">\n<li><code>Can_MainFunction_Write()</code>: Zyklischer Aufruf des Treibers durch den Scheduler</li>\n<li><code>Check for pending TX confirmations()</code>: Hardware-Abfrage des CAN-Treibers an den Controller</li>\n<li><code>CanIf_TxConfirmation(PduIdType)</code>: Callback des CAN-Treibers an das CAN-Interface</li>\n<li><code>&lt;User_TxConfirmation&gt;(PduIdType)</code>: Konfigurierbarer Callback des CAN-Interfaces an die übergeordnete Schicht (CanIf-Nutzer)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf ist in einen <code>loop Cyclic Task of Interface</code> eingebettet:</p>\n<ol class=\"fig-list\">\n<li><code>BSW Scheduler</code> ruft synchron <code>Can_MainFunction_Write()</code> auf dem Modul <code>Can</code> auf.</li>\n<li><code>Can</code> prüft hardwarenah beim <code>CanController</code> ausstehende Sende-Bestätigungen (<code>Check for pending TX confirmations()</code>).</li>\n<li>In einem <code>alt</code>-Fragment (<code>Pending Tx confirmation</code>) wird differenziert:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[Tx confirmation is pending ]</code>: <code>Can</code> ruft <code>CanIf_TxConfirmation(PduIdType)</code> auf; <code>CanIf</code> leitet die Bestätigung über <code>&lt;User_TxConfirmation&gt;(PduIdType)</code> an den entsprechenden <code>CanIf User</code> weiter. Nach Rückkehr beider Aufrufe kehrt die Kontrolle zu <code>Can</code> zurück.</li>\n<li>Zweig <code>[No Tx confirmation is pending]</code>: Keine weiteren Aktionen im Treiber oder Interface.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>Can_MainFunction_Write()</code> kehrt zum <code>BSW Scheduler</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert das Polling-Verhalten im Gegensatz zum interruptgetriebenen Bestätigungspfad. Bei Verzicht auf TX-Interrupts des Controllers muss die zyklische Task <code>Can_MainFunction_Write()</code> in ausreichender Frequenz durch den BSW Scheduler getaktet werden, um Latenzen bei der Sende-Bestätigung an obere Schichten (<code>CanIf User</code>) zu minimieren. Die PduIdType-Zuordnung erfolgt hierarchisch über die konfigurierte Transmit-PDU-ID.</p>"}], "trans": [{"from": "FIG-659f3789f0bde91b", "to": "FIG-c46f90c9325a2a03", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
